import json, sys

data = json.load(sys.stdin)
open('after-cpm-packages.json','w').write(json.dumps(data, indent=2))

with open('baseline-packages.json') as f:
    baseline = json.load(f)

def extract(d):
    result = {}
    for proj in d.get('projects', []):
        name = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                key = (name, fw['framework'], pkg['id'])
                result[key] = pkg['resolvedVersion']
    return result

before = extract(baseline)
after = extract(data)

all_keys = sorted(set(before.keys()) | set(after.keys()))
changes = []
unchanged = []
for k in all_keys:
    b = before.get(k)
    a = after.get(k)
    if b != a:
        changes.append((k, b, a))
    else:
        unchanged.append((k, a))

print('=== CHANGES ===')
if changes:
    for (proj, fw, pkg), b, a in changes:
        status = 'Added' if not b else 'Removed' if not a else 'Aligned to highest version'
        print(f'{proj} ({fw}): {pkg} {b or \"N/A\"} -> {a or \"N/A\"} [{status}]')
else:
    print('None')

print()
print('=== UNCHANGED ===')
for (proj, fw, pkg), v in unchanged:
    print(f'{proj} ({fw}): {pkg} {v}')
"

